const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Area between Elkhorn and Platte Rivers near Omaha
  const geometry = ee.Geometry.Polygon([[
    [-96.3, 41.2], [-96.0, 41.2], [-96.0, 41.4], [-96.3, 41.4], [-96.3, 41.2]
  ]]);

  // 2. Data Acquisition - Sentinel-2 for water detection
  function getMarchCollection(year) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(year + '-03-01', year + '-03-31')
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
  }

  const col2018 = getMarchCollection('2018');
  const col2019 = getMarchCollection('2019');

  // Check for empty collections
  const size2018 = col2018.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`2018 March Images: ${size2018}`);
  console.log(`2019 March Images: ${size2019}`);

  if (size2018 === 0 || size2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create median composites and calculate NDWI
  function calculateWaterArea(collection) {
    const composite = collection.median();

    // Calculate NDWI (Normalized Difference Water Index)
    const ndwi = composite.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0 indicates water)
    const waterMask = ndwi.gt(0);

    // Count water pixels
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e9
    }).get('NDWI');

    return waterCount.getInfo();
  }

  const water2018 = calculateWaterArea(col2018);
  const water2019 = calculateWaterArea(col2019);

  console.log(`2018 Water Pixels: ${water2018}`);
  console.log(`2019 Water Pixels: ${water2019}`);

  // Check for no valid pixels
  if (water2018 === 0 || water2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (water2018 === null || water2019 === null || 
      isNaN(water2018) || isNaN(water2019)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Final comparison
  const increase = water2019 > water2018;
  const percentChange = ((water2019 - water2018) / water2018 * 100).toFixed(1);

  console.log(`Water change: ${percentChange}%`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
